def find_in_mountain_array(target, mountain_arr):
    n = mountain_arr.length()
    lo, hi = 0, n - 1
    while lo < hi:                                  # phase 1: find the peak
        mid = (lo + hi) // 2
        if mountain_arr.get(mid) < mountain_arr.get(mid + 1):
            lo = mid + 1
        else:
            hi = mid
    peak = lo

    lo, hi = 0, peak                                  # phase 2: search increasing side
    while lo <= hi:
        mid = (lo + hi) // 2
        val = mountain_arr.get(mid)
        if val == target:
            return mid
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1

    lo, hi = peak, n - 1                               # phase 3: search decreasing side
    while lo <= hi:
        mid = (lo + hi) // 2
        val = mountain_arr.get(mid)
        if val == target:
            return mid
        if val > target:                                  # reversed comparison direction
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

