            if (mountainArr.get(mid) < mountainArr.get(mid + 1)) lo = mid + 1;
            else hi = mid;
        }
        int peak = lo;

        lo = 0; hi = peak;                                     // phase 2: search increasing side
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int val = mountainArr.get(mid);
            if (val == target) return mid;
            if (val < target) lo = mid + 1; else hi = mid - 1;
        }

        lo = peak; hi = n - 1;                                  // phase 3: search decreasing side
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int val = mountainArr.get(mid);
            if (val == target) return mid;
            if (val > target) lo = mid + 1; else hi = mid - 1;    // reversed comparison
        }
        return -1;
    }
}

